// Map ERP KPI response to ISC /api/v1/kpis/import and POST directly.
// ISC expects: { slug: string, values: Record<kpiId, numericValue> }
// Adjust item.kpi_code and item.current_value to match your ERP's fields.
const raw = JSON.parse(inputData.erpKpisRaw || '[]');
const values = {};
for (const item of raw) {
  // item.kpi_code → ISC kpi ID, item.current_value → numeric value
  values[String(item.kpi_code)] = Number(item.current_value);
}
// Change 'erp-sync' to match the toolkit slug you use in ISC.
const body = JSON.stringify({ slug: 'erp-sync', values });
const resp = await fetch(`https://${inputData.iscDomain}/api/v1/kpis/import`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'x-api-key': inputData.iscApiKey },
  body,
});
const result = await resp.json().catch(() => ({}));
return { status: resp.status, ok: resp.ok ? 'true' : 'false', kpiCount: Object.keys(values).length };

// Map ERP supplier response to ISC /api/v1/suppliers/import and POST directly.
// ISC requires each supplier to have 'id' and 'name'. All other fields optional.
// Adjust item.supplier_code, item.supplier_name, item.classification, item.country_code for your ERP.
const raw = JSON.parse(inputData.erpSuppliersRaw || '[]');
const suppliers = raw.map(item => ({
  id:      String(item.supplier_code),   // required — unique identifier
  name:    String(item.supplier_name),   // required — display name
  tier:    item.classification || 'Approved',
  country: item.country_code   || '',
}));
const body = JSON.stringify({ suppliers });
const resp = await fetch(`https://${inputData.iscDomain}/api/v1/suppliers/import`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'x-api-key': inputData.iscApiKey },
  body,
});
const result = await resp.json().catch(() => ({}));
return { status: resp.status, ok: resp.ok ? 'true' : 'false', supplierCount: suppliers.length };
